'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dormqr = require( './../lib/dormqr.js' );


// VARIABLES //

var LAYOUTS = [
	'row-major',
	'column-major'
];
var SIDES = [
	'left',
	'right'
];
var TRANSPOSES = [
	'no-transpose',
	'transpose'
];
var opts = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {string} order - storage layout
* @param {string} side - storage layout
* @param {string} trans - storage layout
* @param {PositiveInteger} N - number of elements along each dimension
* @returns {Function} benchmark function
*/
function createBenchmark( order, side, trans, N ) {
	var LWORK = N * 32;
	var WORK = new Float64Array( LWORK );
	var TAU = discreteUniform(N, 1.0, 2.0, opts);
	var A = discreteUniform( N*N, 1.0, 10.0, opts );
	var C = discreteUniform( N*N, 1.0, 10.0, opts );

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var d;
		var i;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			d = dormqr( order, side, trans, N, N, N, A, N, TAU, C, N, WORK, LWORK );
			if ( d < 0 ) {
				b.fail( 'should return a success status code' );
			}
		}
		b.toc();
		if ( d < 0 ) {
			b.fail( 'should return a success status code' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var trans;
	var side;
	var min;
	var max;
	var ord;
	var N;
	var f;
	var i;
	var j;
	var k;
	var l;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( k = 0; k < LAYOUTS.length; k++ ) {
		ord = LAYOUTS[ k ];
		for ( l = 0; l < TRANSPOSES.length; l++ ) {
			trans = TRANSPOSES[ l ];
			for ( j = 0; j < SIDES.length; j++ ) {
				side = SIDES[ j ];
				for ( i = min; i <= max; i++ ) {
					N = floor( pow( pow( 10, i ), 1.0/2.0 ) );
					f = createBenchmark( ord, side, trans, N );
					bench( format( '%s::square_matrix:order=%s,side=%s,trans=%s,size=%d', pkg, ord, side, trans, N*N ), f );
				}
			}
		}
	}
}

main();
